import {catalogueOptions,localQuote} from './matcher.mjs';
import {createPlanner,parseBrief,assess,reasonText,pricePlan} from './planner.mjs';
const $=s=>document.querySelector(s),form=$('#match-form'),dialog=$('#profile-dialog');
const money=n=>new Intl.NumberFormat('ru-RU').format(n),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const date=d=>new Intl.DateTimeFormat('ru-RU',{day:'numeric',month:'long',timeZone:'UTC'}).format(new Date(d+'T00:00:00Z'));
let catalogue=[],options,planner,result,activeTab='selection',excludedFilter='all',reserve=20,previousRequest=null,currentProfile=null,dialogTab='pricing';
const defaultRequest={city:'Алматы',date:'2026-10-15',category:'Ведущий',event_format:'корпоратив',budget_kzt:1200000,duration_hours:'',language:'',brief:'спокойный ведущий делового форума'};
const statusLabel={confirmed:'Подтверждено',related:'Есть близкий опыт',unknown:'Нет подтверждения',conflict:'Противоречие'};
function updateCategories(preferred=form.elements.category.value){if(!options)return;const available=options.categories_by_city[form.elements.city.value]||[],all=[...new Set(Object.values(options.categories_by_city).flat())].sort((a,b)=>a.localeCompare(b,'ru'));const absent=all.filter(c=>!available.includes(c)),option=c=>`<option value="${esc(c)}">${esc(c)}</option>`;form.elements.category.innerHTML=`<optgroup label="Есть в городе">${available.map(option).join('')}</optgroup>${absent.length?`<optgroup label="Нет в этом городе">${absent.map(option).join('')}</optgroup>`:''}`;form.elements.category.value=all.includes(preferred)?preferred:available[0];}
function showBrief(){const parsed=parseBrief(form.elements.brief.value);$('#brief-preview').innerHTML=parsed.map(p=>`<span>${p.kind==='condition'?'Условие':'Пожелание'}: ${esc(p.label)}</span>`).join('');}
function writeForm(r){form.elements.city.value=r.city;updateCategories(r.category);for(const [key,value] of Object.entries(r)){const field=form.elements.namedItem(key);if(field)field.value=value??'';}showBrief();}
function provenance(p){return `<div class="provenance">${p.synthetic?'<span>Синтетический профиль</span>':''}${p.city_imputed?'<span>Город восстановлен в датасете</span>':''}${p.price_imputed?'<span>Стартовая цена оценочная</span>':''}</div>`;}
function priceLabel(p){const cost=pricePlan(p,reserve);return `${money(cost.low)}–${money(cost.high)} ₸`;}
function cautions(p){const checks=assess(p,result.parsed),unknown=checks.filter(c=>c.status==='unknown'||c.status==='conflict');const lines=unknown.map(c=>`${c.label}: ${c.status==='conflict'?'есть противоречие':'нет подтверждения в профиле'}`);if(!lines.length)lines.push(result.parsed.length?'Похожие формулировки не гарантируют полное совпадение стиля.':'Стиль не задан — сравните опыт из описания.');if(pricePlan(p,reserve).high>result.request.budget_kzt)lines.push('С резервом расчёт выходит за бюджет.');else lines.push('Верхняя цена и состав пакета в каталоге не указаны.');return lines.slice(0,3);}
function card(p,i){return `<article class="card"><div class="card-header"><span class="rank-no" aria-hidden="true">0${i+1}</span><div class="card-name"><h3>${esc(p.name)}</h3><p>${esc(result.request.category)} / ${esc(p.city)}</p></div><div class="card-price"><strong>${priceLabel(p)}</strong><small>Расчёт: цена «от» + резерв ${reserve}%</small></div></div><div class="card-facts"><span class="fact">✓ ${date(result.request.date)} по каталогу</span><span class="fact">✓ ${esc(result.request.event_format)}</span>${result.request.language?`<span class="fact">✓ ${esc(result.request.language)}</span>`:''}<span class="fact">✓ Стартовая цена в бюджете</span></div><div class="card-inside"><div><span class="micro-label">ЧЕМ ВЫДЕЛЯЕТСЯ / ИЗ ПРОФИЛЯ</span><blockquote class="card-quote">«${esc(p.evidence_quote)}»</blockquote></div><div class="card-cautions"><span class="micro-label">ЧТО ПОКА НЕИЗВЕСТНО</span>${cautions(p).map(s=>`<p>${esc(s)}</p>`).join('')}</div></div>${provenance(p)}<button type="button" class="card-action" data-profile="${esc(p.id)}">Подробнее · прайс и соответствие <span>↗</span></button></article>`;}
function setTab(tab,focus=false){activeTab=tab;document.querySelectorAll('[data-tab]').forEach(b=>{const selected=b.dataset.tab===tab;b.setAttribute('aria-selected',String(selected));b.tabIndex=selected?0:-1;if(selected&&focus)b.focus();});for(const id of ['selection','excluded','alternatives'])$('#panel-'+id).hidden=id!==tab;}
function renderSelection(){const panel=$('#panel-selection');let html='';if(previousRequest)html+='<button type="button" class="undo" data-undo>↶ Вернуть исходные условия</button>';if(!result.cards.length)html+=`<div class="empty"><span class="empty-symbol">…</span><h3>${result.status==='category_absent'?'Здесь пока нет этой категории.':'Точного совпадения пока нет.'}</h3><p>${result.status==='category_absent'?'Посмотрим тот же запрос в других городах.':'Проверим, какое изменение даты, бюджета или длительности откроет новые варианты.'}</p></div>`;else html+=result.cards.map(card).join('');if(result.alternatives.length)html+=`<div class="plan-invite"><p><b>${result.eligible<3?'Есть другой ход.':'Хотите больше выбора?'}</b>Проверенные варианты изменения условий: ${result.alternatives.length}.</p><button type="button" data-open-plan>Открыть план Б ↗</button></div>`;else if(!result.cards.length)html+='<p class="tab-intro">В рамках даты, бюджета и длительности подтверждённых альтернатив нет. Попробуйте другую категорию или пересмотрите пожелания.</p>';panel.innerHTML=html;}
function renderExcluded(){const reasons=[...new Set(result.excluded.flatMap(p=>p.failures))];const rows=result.excluded.filter(p=>excludedFilter==='all'||excludedFilter==='eligible'&&!p.failures.length||p.failures.includes(excludedFilter));$('#panel-excluded').innerHTML=`<div class="tab-intro"><h3>Кто остался за кадром</h3><p>${esc(result.request.category)} · ${esc(result.request.city)}. Откройте имя, чтобы увидеть профиль, расчёт цены и причины. Подходящие вне тройки остаются доступны.</p></div><div class="filter-row"><button type="button" data-filter="all" aria-pressed="${excludedFilter==='all'}">Все · ${result.excluded.length}</button>${result.excluded.some(p=>!p.failures.length)?`<button type="button" data-filter="eligible" aria-pressed="${excludedFilter==='eligible'}">Подходят вне тройки</button>`:''}${reasons.map(k=>`<button type="button" data-filter="${k}" aria-pressed="${excludedFilter===k}">${esc(reasonText[k])}</button>`).join('')}</div>${rows.length?rows.map(p=>`<button type="button" class="excluded-row" data-profile="${esc(p.id)}"><span><b>${esc(p.name)}</b><small>${p.failures.length?p.failures.map(k=>esc(reasonText[k])).join(' · '):'Все условия соблюдены · ниже в порядке рекомендаций'}</small></span><span class="row-price">от ${money(p.price_from_kzt)} ₸<span>↗</span></span></button>`).join(''):'<div class="empty"><p>В этой группе больше никого нет.</p></div>'}`;}
function patchText(a){return Object.entries(a.patch).map(([key,value])=>({date:()=>`${date(result.request.date)} → ${date(value)}`,budget_kzt:()=>`${money(result.request.budget_kzt)} → ${money(value)} ₸`,duration_hours:()=>`${result.request.duration_hours} → ${value} ч`,city:()=>`${result.request.city} → ${value}`}[key]())).join('<br>');}
function renderAlternatives(){const types={date:'Сдвинуть дату',budget:'Изменить бюджет',duration:'Сократить длительность',city:'Посмотреть другой город',combined:'Изменить несколько условий'};$('#panel-alternatives').innerHTML=`<div class="tab-intro"><h3>Не тупик. Поворот.</h3><p>Пересчитали каталог. Здесь только изменения, которые действительно увеличивают число подходящих кандидатов. Пожелания, категория и формат сохраняются.</p></div>${previousRequest?'<button type="button" class="undo" data-undo>↶ Вернуть исходные условия</button>':''}${result.alternatives.map((a,i)=>`<article class="alternative"><div><div class="alt-type">${types[a.kind]}</div><h4>${patchText(a)}</h4><p>${a.kind==='combined'?'Одного изменения оказалось недостаточно.':a.kind==='date'?'Ближайшая дата с большим выбором.':a.kind==='budget'?'Минимальный порог стартовой цены, который добавляет кандидатов.':a.kind==='duration'?'Ближайший меньший лимит часов, который добавляет кандидатов.':'Те же условия в другом городе.'}</p></div><div class="alt-result">${a.count}<small>подходит вместо ${result.eligible}</small></div><button type="button" data-apply="${i}">Применить и посмотреть <span>↗</span></button></article>`).join('')||'<div class="empty"><h3>Простого изменения недостаточно.</h3><p>Изменение даты, бюджета или длительности не добавляет подходящих вариантов. Можно пересмотреть город, категорию, формат или пожелания в брифе.</p></div>'}`;}
function render(){const r=result.request;$('#loading').hidden=true;$('#request-summary').innerHTML=[r.city,r.category,date(r.date)+' 2026',r.event_format,'бюджет '+money(r.budget_kzt)+' ₸',...(r.language?[r.language]:[]),...(r.duration_hours?[r.duration_hours+' ч']:[])].map(s=>`<span>${esc(s)}</span>`).join('');$('#selection-count').textContent=result.cards.length;$('#excluded-count').textContent=result.excluded.length;$('#alternative-count').textContent=result.alternatives.length;renderSelection();renderExcluded();renderAlternatives();setTab(activeTab);$('#update-status').textContent=`Подбор обновлён. Подходят ${result.eligible} из ${result.total}. В тройке: ${result.cards.map(p=>p.name).join(', ')||'никого'}.`;$('#form-error').textContent='';$('#dirty-note').hidden=true;}
function run(input,{keepPrevious=false}={}){if(!planner)throw Error('Каталог ещё загружается.');const next=planner(input);if(!keepPrevious)previousRequest=null;result=next;excludedFilter='all';writeForm(next.request);render();return result;}
function submit(){try{activeTab='selection';run(Object.fromEntries(new FormData(form)));if(matchMedia('(max-width:760px)').matches)$('.selection').scrollIntoView({behavior:'smooth'});}catch(e){$('#form-error').textContent=e.message;}}
form.addEventListener('submit',e=>{e.preventDefault();submit();});
form.elements.city.addEventListener('change',()=>updateCategories());
form.addEventListener('input',()=>{showBrief();$('#dirty-note').hidden=false;});form.addEventListener('change',()=>{$('#dirty-note').hidden=false;});
$('#reset').addEventListener('click',()=>{try{activeTab='selection';run(defaultRequest);}catch(e){$('#form-error').textContent=e.message;}});
function bindTabKeyboard(container,selector,action){container.addEventListener('keydown',e=>{if(!e.target.matches(selector)||!['ArrowRight','ArrowLeft','Home','End'].includes(e.key))return;e.preventDefault();const buttons=[...container.querySelectorAll(selector)],n=buttons.indexOf(e.target),index=e.key==='Home'?0:e.key==='End'?buttons.length-1:(n+(e.key==='ArrowRight'?1:-1)+buttons.length)%buttons.length;action(buttons[index]);buttons[index].focus();});}
document.querySelector('.navigation').addEventListener('click',e=>{const b=e.target.closest('[data-tab]');if(b)setTab(b.dataset.tab);});bindTabKeyboard($('.navigation'),'[data-tab]',b=>setTab(b.dataset.tab));
function pricePanel(p){const cost=pricePlan(p,reserve);return `<h3>Прайс и расчёт бюджета</h3><div class="cost-total"><div><small>РАСЧЁТНЫЙ ДИАПАЗОН · НЕ ТАРИФ ПОДРЯДЧИКА</small><strong>от ${money(cost.low)} до ${money(cost.high)} ₸</strong></div></div><table class="cost-table"><tbody><tr><th scope="row">Стартовая стоимость<small>${p.price_imputed?'Оценочная цена из исходного датасета':'Цена «от» из каталога'}</small></th><td>${money(cost.base)} ₸</td></tr><tr><th scope="row">Плановый резерв ${reserve}%<small>Наше допущение для планирования; не услуга и не наценка подрядчика</small></th><td>+ ${money(cost.reserve)} ₸</td></tr><tr><th scope="row">Бюджет с резервом</th><td><b>${money(cost.high)} ₸</b></td></tr><tr><th scope="row">Верхняя цена подрядчика</th><td>Нет данных</td></tr><tr><th scope="row">Состав базового пакета</th><td>Не указан</td></tr><tr><th scope="row">Дополнительный час</th><td>Нет тарифа</td></tr><tr><th scope="row">Выезд, оборудование, допуслуги</th><td>Нет разбивки</td></tr></tbody></table><div class="cost-controls"><label for="reserve">Резерв для всех расчётов</label><select id="reserve">${[0,10,20,30,50].map(n=>`<option value="${n}" ${n===reserve?'selected':''}>${n}%</option>`).join('')}</select></div><p class="price-disclaimer">Диапазон помогает заложить бюджет. Это не коммерческое предложение: верхняя сумма рассчитана по выбранному резерву и не гарантирует итоговую стоимость. Распределение цены по услугам отсутствует в исходных данных.</p>${cost.high>result.request.budget_kzt?`<p class="price-disclaimer">С резервом выше вашего бюджета на ${money(cost.high-result.request.budget_kzt)} ₸. Подбор фильтруется по стартовой цене.</p>`:''}`;}
function fitPanel(p){const findings=assess(p,result.parsed),excluded=result.excluded.find(c=>c.id===p.id),fail=excluded?.failures||[];const r=result.request;return `<h3>Почему подходит — и где компромисс</h3>${fail.length?`<p class="price-disclaimer">Не вошёл по условиям: ${fail.map(k=>esc(reasonText[k])).join('; ')}.</p>`:excluded?'<p>Все условия соблюдены. Этот профиль оказался ниже тройки при сравнении пожеланий с описаниями.</p>':'<p>Профиль вошёл в тройку по условиям и соответствию пожеланиям.</p>'}<dl class="detail-facts"><div><dt>Дата · ${date(r.date)}</dt><dd>${p.busy_dates.includes(r.date)?'Занят':'Доступен'} по календарю каталога</dd></div><div><dt>Бюджет · ${money(r.budget_kzt)} ₸</dt><dd>${p.price_from_kzt<=r.budget_kzt?'Стартовая цена укладывается':'Стартовая цена выше на '+money(p.price_from_kzt-r.budget_kzt)+' ₸'}</dd></div><div><dt>Формат · ${esc(r.event_format)}</dt><dd>${p.event_formats.includes(r.event_format)?'Указан в каталоге':'Не указан в каталоге'}</dd></div><div><dt>Длительность</dt><dd>${p.max_hours===null?'Лимит часов не задан':`Лимит: ${p.max_hours} ч`}</dd></div></dl>${findings.length?`<ul class="evidence-list">${findings.map(a=>`<li><strong>${esc(a.label)}</strong><span class="evidence-status ${a.status}">${statusLabel[a.status]}</span><small>${a.quote?esc(a.quote):'В описании нет достаточного подтверждения. Это пожелание не считаем выполненным.'}</small></li>`).join('')}</ul>`:'<p>Особые пожелания не заданы.</p>'}<p class="price-disclaimer">Близкий опыт — совпадение по формулировкам, а не гарантия стиля. Неизвестное не превращаем в подтверждение. Произвольные пожелания пока не разбираются как строгие условия.</p>`;}
function bioPanel(p){return `<h3>Досье из каталога</h3><dl class="detail-facts"><div><dt>Языки</dt><dd>${esc(p.languages.join(', '))}</dd></div><div><dt>Форматы</dt><dd>${esc(p.event_formats.join(', '))}</dd></div><div><dt>Категории</dt><dd>${esc(p.categories.join(', '))}</dd></div><div><dt>Источник</dt><dd>${esc(p.id)} · ${p.synthetic?'синтетический':'анонимизированный'} профиль</dd></div></dl><p class="profile-description">${esc(p.description)}</p>${provenance(p)}`;}
function setDialogTab(tab){dialogTab=tab;dialog.querySelectorAll('[data-dialog-tab]').forEach(b=>{const selected=b.dataset.dialogTab===tab;b.setAttribute('aria-selected',String(selected));b.tabIndex=selected?0:-1;});for(const id of ['pricing','fit','bio'])$('#dialog-'+id).hidden=id!==tab;}
function openProfile(id){const p=catalogue.find(p=>p.id===id);if(!p)return;currentProfile=p;$('#dialog-content').innerHTML=`<div class="dialog-head"><span class="micro-label">ДОСЬЕ / ${esc(p.id)}</span><h2 id="dialog-title">${esc(p.name)}</h2><p>${esc(p.categories.join(' · '))} / ${esc(p.city)}</p></div><div class="dialog-tabs" role="tablist" aria-label="Подробности подрядчика">${[['pricing','Прайс и расчёт'],['fit','Соответствие'],['bio','Полный профиль']].map(([id,label])=>`<button type="button" role="tab" id="dialog-tab-${id}" data-dialog-tab="${id}" aria-controls="dialog-${id}" aria-selected="false" tabindex="-1">${label}</button>`).join('')}</div><div id="dialog-pricing" class="dialog-panel" role="tabpanel" aria-labelledby="dialog-tab-pricing">${pricePanel(p)}</div><div id="dialog-fit" class="dialog-panel" role="tabpanel" aria-labelledby="dialog-tab-fit">${fitPanel(p)}</div><div id="dialog-bio" class="dialog-panel" role="tabpanel" aria-labelledby="dialog-tab-bio">${bioPanel(p)}</div>`;setDialogTab('pricing');dialog.showModal();dialog.scrollTop=0;}
$('.dialog-close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog){const rect=dialog.getBoundingClientRect();if(e.clientX<rect.left||e.clientX>rect.right||e.clientY<rect.top||e.clientY>rect.bottom)dialog.close();}const tab=e.target.closest('[data-dialog-tab]');if(tab)setDialogTab(tab.dataset.dialogTab);});bindTabKeyboard(dialog,'[data-dialog-tab]',b=>setDialogTab(b.dataset.dialogTab));
dialog.addEventListener('change',e=>{if(e.target.id==='reserve'){reserve=Number(e.target.value);$('#dialog-pricing').innerHTML=pricePanel(currentProfile);renderSelection();$('#reserve').focus();}});
document.addEventListener('click',e=>{const profile=e.target.closest('[data-profile]');if(profile)openProfile(profile.dataset.profile);const filter=e.target.closest('[data-filter]');if(filter){excludedFilter=filter.dataset.filter;renderExcluded();document.querySelector(`[data-filter="${excludedFilter}"]`)?.focus();}if(e.target.closest('[data-open-plan]'))setTab('alternatives',true);const apply=e.target.closest('[data-apply]');if(apply){const a=result.alternatives[Number(apply.dataset.apply)];previousRequest={...result.request};activeTab='selection';run({...result.request,...a.patch},{keepPrevious:true});$('#tab-selection').focus();}if(e.target.closest('[data-undo]')&&previousRequest){const restore=previousRequest;activeTab='selection';run(restore);$('#tab-selection').focus();}const demo=e.target.closest('[data-demo]');if(demo){const r={...defaultRequest};if(demo.dataset.demo==='december')r.date='2026-12-19';if(demo.dataset.demo==='empty')r.budget_kzt=100000;activeTab='selection';try{run(r);}catch(error){$('#form-error').textContent=error.message;}}});
async function init(){try{const response=await fetch('./catalogue.json');if(!response.ok)throw Error('Каталог не загрузился.');catalogue=await response.json();planner=createPlanner(catalogue);options=catalogueOptions(catalogue);form.elements.city.innerHTML=options.cities.map(c=>`<option>${esc(c)}</option>`).join('');$('#submit').disabled=false;run(defaultRequest);}catch(e){$('#loading').innerHTML='Не удалось загрузить каталог. <button type="button" id="retry">Повторить</button>';$('#retry').addEventListener('click',init);$('#form-error').textContent=e.message;}}
if(document.modelContext?.registerTool){const lifecycle=new AbortController();window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});try{Promise.resolve(document.modelContext.registerTool({name:'find_event_contractors',title:'Подобрать event-подрядчиков',description:'Run catalogue matching, update the visible brief and results, and return verified alternatives. Does not book or contact anyone.',inputSchema:{type:'object',properties:{city:{type:'string'},date:{type:'string'},event_format:{type:'string'},category:{type:'string'},budget_kzt:{type:'integer',minimum:1},duration_hours:{type:'number',exclusiveMinimum:0},language:{type:'string'},brief:{type:'string',maxLength:500}},required:['city','date','event_format','category','budget_kzt'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute(input){activeTab='selection';const r=run(input);return {status:r.status,eligible:r.eligible,cards:r.cards.map(p=>({id:p.id,name:p.name,starting_price:p.price_from_kzt})),parsed:r.parsed,alternatives:r.alternatives,excluded:r.excluded.map(p=>({id:p.id,name:p.name,reasons:p.failures}))};}},{signal:lifecycle.signal})).catch(()=>{});}catch{}}
showBrief();init();
